<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model;
class StudentApplication extends Model { protected $fillable=['user_id','registration_number','admission_period_id','admission_wave_id','status','submitted_at','verified_at']; protected $casts=['submitted_at'=>'datetime','verified_at'=>'datetime']; public function user(){return $this->belongsTo(User::class);} public function period(){return $this->belongsTo(AdmissionPeriod::class,'admission_period_id');} public function wave(){return $this->belongsTo(AdmissionWave::class,'admission_wave_id');} public function studentProfile(){return $this->hasOne(StudentProfile::class);} public function parentProfile(){return $this->hasOne(ParentProfile::class);} public function documents(){return $this->hasMany(ApplicationDocument::class);} public function statusHistories(){return $this->hasMany(ApplicationStatusHistory::class);} }
